constexpr int kVpIntervals = 6;           // buckets: <=-1, 0, 1, 2, 3, >=4
volatile LONG g_vpDepthHist[kEyes][kVpRing]        = {};
volatile LONG g_vpIntervalHist[kEyes][kVpIntervals] = {};
bool  g_mvHaveBoth[kEyes] = {};

