// Folds the current bind's tally into its signature. Called on every transition
// out of a swapchain bind - to a different signature, or to a target that is
// not ours at all - and once more at report time.
void UiFlushActive()
{
    const LONG slot = g_uiActiveSig;
    g_uiActiveSig = -1;
    const LONG d = g_uiActiveDraws;
    const LONG v = g_uiActiveVerts;
    g_uiActiveDraws = 0;
    g_uiActiveVerts = 0;
    if (slot < 0 || slot >= kUiSigs) { return; }
    UiSig& s = g_uiSig[slot];
    s.draws += d;
    s.verts += v;
    if (d == 0) { ++s.emptyBinds; }
    if (s.minPerBind < 0 || d < s.minPerBind) { s.minPerBind = d; }
    if (d > s.maxPerBind) { s.maxPerBind = d; }
}

// A bind waiting for its viewport. The pair only becomes a signature once
// RSSetViewports fires, because that is the only moment the viewport is known
// to belong to this draw.
bool  g_uiPendBind = false;
UINT  g_uiPendViews = 0, g_uiPendW = 0, g_uiPendH = 0;
bool  g_uiPendDepth = false;
int   g_uiPendKind  = 0;   // 0 = the double-wide swapchain, 1 = a per-eye target

void NoteUiSig(float vpX, float vpY, float vpW, float vpH)
{
    // A new swapchain bind ends the previous one: bank whatever it drew before
    // switching, or the tallies run together and every verdict is meaningless.
    UiFlushActive();

    const LONG n = g_uiSigCount;
    for (LONG i = 0; i < n && i < kUiSigs; ++i) {
        UiSig& s = g_uiSig[i];
        if (s.kind == g_uiPendKind && s.numViews == g_uiPendViews && s.hasDepth == g_uiPendDepth &&
            s.w == g_uiPendW && s.h == g_uiPendH &&
            s.vpX == vpX && s.vpY == vpY && s.vpW == vpW && s.vpH == vpH) {
            InterlockedIncrement(&s.count);
            g_uiActiveSig = i;
            return;
        }
    }
    if (n >= kUiSigs) { return; }
    const LONG slot = InterlockedIncrement(&g_uiSigCount) - 1;
    if (slot >= kUiSigs) { return; }
    UiSig& s = g_uiSig[slot];
    s.numViews = g_uiPendViews; s.hasDepth = g_uiPendDepth; s.kind = g_uiPendKind;
    s.w = g_uiPendW; s.h = g_uiPendH;
    s.vpX = vpX; s.vpY = vpY; s.vpW = vpW; s.vpH = vpH;
    s.count = 1;
    s.countPrev = 0;
    s.draws = 0; s.verts = 0;
    s.minPerBind = -1; s.maxPerBind = 0; s.emptyBinds = 0;
    g_uiActiveSig = slot;
    LOG("[DLSSUI] new signature #%ld: %u target(s), depth %s, target %ux%u, viewport "
        "(%.0f,%.0f %.0fx%.0f)",
        slot, s.numViews, s.hasDepth ? "YES" : "no", s.w, s.h, vpX, vpY, vpW, vpH);
}

// One place that decides what a render-target bind means for the census, used
// by BOTH OMSetRenderTargets (slot 33) and OMSetRenderTargetsAndUnorderedAccess
// Views (slot 34).
//
// Slot 34 was missing in the first working run and it cost the result: RT
// changes through it never closed the attribution window, so a whole frame's
// draws (200 per bind, 2474 at worst) landed on the last swapchain bind. A
// counter must cover every call site of the thing it claims to count - the
// same failure the left-arm restore counter paid for.
//
// TWO kinds of target are now tracked:
//   kind 0  the layer's OWN double-wide eye swapchain, matched by IDENTITY
//   kind 1  a PER-EYE target - half the swapchain's width, same height. That is
//           _RIFT_L / _RIFT_R, and whether the UI is drawn there is what
//           decides if the HUD survives upscaling sharp or gets upscaled soft.
void UiNoteRtBind(UINT NumViews, ID3D11RenderTargetView* const* ppRTVs,
                  ID3D11DepthStencilView* pDSV)
{
    if (g_eyeSwapCount <= 0 || !ppRTVs || NumViews < 1) {
        // A bind with no render targets still ENDS the previous one.
        g_uiPendBind = false;
        UiFlushActive();
        return;
    }
    bool matched = false;
    for (UINT i = 0; i < NumViews && i < 8; ++i) {
        D3D11_TEXTURE2D_DESC ud = {};
        ID3D11Texture2D* ut = TexOfView(ppRTVs[i], ud);
        if (!ut) { continue; }
        bool isSwap = false;
        for (LONG k = 0; k < g_eyeSwapCount && k < 8; ++k) {
            if (g_eyeSwapTex[k] == ut) { isSwap = true; break; }
        }
        ut->Release();
        const bool isEye = !isSwap && g_eyeSwapW > 0 &&
                           ud.Width * 2 == g_eyeSwapW && ud.Height == g_eyeSwapH;
        if (!isSwap && !isEye) { continue; }
        matched       = true;
        g_uiPendBind  = true;
        g_uiPendKind  = isSwap ? 0 : 1;
        g_uiPendViews = NumViews;
        g_uiPendDepth = (pDSV != nullptr);
        g_uiPendW     = ud.Width;
        g_uiPendH     = ud.Height;
        break;
    }
    if (!matched) {
        g_uiPendBind = false;
        UiFlushActive();
    }
}

