inline unsigned H(const void* p) { size_t x = reinterpret_cast<size_t>(p); x ^= x >> 17; x *= 0x9E3779B1u; return static_cast<unsigned>(x ^ (x >> 15)); }

bool Rd2(const void* p, float out[2])
{
    __try { memcpy(out, p, 8); return true; } __except (EXCEPTION_EXECUTE_HANDLER) { return false; }
}

const Mat* MatOf(const void* cb)
{
    unsigned i = H(cb) & 4095u;
    for (int k = 0; k < 8; ++k, i = (i + 1) & 4095u) {
        if (g_mat[i].p == cb) { return &g_mat[i]; }
        if (!g_mat[i].p) { return nullptr; }
    }
    return nullptr;
}

